CREATE TABLE `mapids` (
  `mapid` int(10) NOT NULL DEFAULT '0',
  `locationname` varchar(45) DEFAULT NULL,
  `monster_amount` float unsigned NOT NULL DEFAULT '1',
  `drop_rate` float unsigned NOT NULL DEFAULT '1',
  `exp_rate` float NOT NULL DEFAULT '1',
  `underwater` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `markable` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `teleportable` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `escapable` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `resurrection` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `painwand` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `penalty` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `take_pets` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `recall_pets` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `usable_item` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `usable_skill` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `polyable` tinyint(1) unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`mapid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

